"""Generate reference/eic-stack-snapshot.yaml from eic/containers."""

from __future__ import annotations

import datetime as dt
import re

import yaml

from .repo import Repo
from .shell import gh_api, gh_file

HEADER = """\
# GENERATED by `ssr refresh-stack` - do not edit by hand.
#
# What the EIC software environment (eic-shell, eic_xl image) ships, taken from eic/containers.
#   specs:    the top-level specs of the eic_xl spack environment (installed explicitly).
#   versions: the version each package is pinned to in the shared packages.yaml (`require: '@...'`),
#             for every package that has a pin; this includes EIC packages built into the image
#             outside the spec list (for example eicrecon, epic, edm4eic).
"""


def _spec_name(spec: str) -> str:
    return re.split(r"[\s@+~%^]", spec.strip(), maxsplit=1)[0]


def snapshot(repo: Repo) -> dict:
    st = repo.config["stack"]
    src = st["containers_repo"]
    ref = st.get("containers_ref", "master")
    sha = gh_api(f"repos/{src}/commits/{ref}")["sha"]
    env = yaml.safe_load(gh_file(src, st["environment_file"], sha))
    pkgs = yaml.safe_load(gh_file(src, st["packages_file"], sha))["packages"]

    specs = sorted({_spec_name(s) for s in env["spack"]["specs"] if isinstance(s, str)})
    versions = {}
    for name, conf in sorted(pkgs.items()):
        req = (conf or {}).get("require") if isinstance(conf, dict) else None
        if not isinstance(req, list):
            continue
        for r in req:
            if isinstance(r, str) and r.startswith("@"):
                versions[name] = r[1:]
                break
    return {
        "source": {
            "repo": src,
            "commit": sha,
            "environment_file": st["environment_file"],
            "packages_file": st["packages_file"],
            "retrieved": dt.date.today().isoformat(),
        },
        "specs": specs,
        "versions": versions,
    }


def write_snapshot(repo: Repo) -> None:
    data = snapshot(repo)
    path = repo.root / "reference" / "eic-stack-snapshot.yaml"
    path.write_text(HEADER + yaml.safe_dump(data, sort_keys=False, width=100), encoding="utf-8")
    print(f"wrote {path.relative_to(repo.root)} ({len(data['specs'])} specs, {len(data['versions'])} pinned versions, "
          f"{data['source']['repo']}@{data['source']['commit'][:12]})")


def load_snapshot(repo: Repo) -> dict:
    path = repo.root / "reference" / "eic-stack-snapshot.yaml"
    return yaml.safe_load(path.read_text()) if path.is_file() else {"specs": [], "versions": {}}
